'use strict';

// FUNCTIONS //

/**
* Checks the native signed32 active envelope.
* @private
* @param {PositiveInteger} N - order
* @param {integer} s1 - first stride
* @param {integer} s2 - second stride
* @param {integer} offset - offset
* @returns {boolean} whether metadata fits
*/
function envelope( N, s1, s2, offset ) {
	var lo;
	var hi;
	var a;
	var b;
	a = (N-1)*s1;
	b = (N-1)*s2;
	lo = offset + ((a < 0) ? a : 0) + ((b < 0) ? b : 0);
	hi = offset + ((a > 0) ? a : 0) + ((b > 0) ? b : 0);
	return lo >= 0 && hi <= 2147483647;
}


// MAIN //

/**
* Restricts dispatch to the native bridge's conservative signed32 domain.
* @private
* @param {ArrayLike} args - already validated normalized arguments
* @returns {boolean} whether native metadata is representable
*/
function canUseNative( args ) {
	var indices;
	var x;
	var i;
	var N;
	N = args[2];
	if ( N > 2147483647 ) {
		return false;
	}
	indices = [ 4, 5, 6, 8, 9, 11, 12 ];
	for ( i = 0; i < indices.length; i++ ) {
		x = args[ indices[i] ];
		if ( x < -2147483647 || x > 2147483647 || (N > 1 && ( x*(N-1) < -2147483647 || x*(N-1) > 2147483647 )) ) {
			return false;
		}
	}
	// Full A bounds are validated, but the CBLAS swap also advances after its last access.
	if ( N > 1 && (args[5]*N < -2147483647 || args[5]*N > 2147483647) ) {
		return false;
	}
	return envelope( N, args[4], args[5], args[6] ) && envelope( N, args[8], 0, args[9] ) && envelope( N, args[11], 0, args[12] );
}

module.exports = canUseNative;
